import { z } from "zod";
import { QuestionSchema, ReadingSchema } from "@/lib/types";

// ──────────────────────────────────────────────────────────
// MOCK EXAM CONTENT (generated by the model — no theory/vocab)
// ──────────────────────────────────────────────────────────
export const MockExamSchema = z.object({
  reading: ReadingSchema,
  questions: z.array(QuestionSchema),
  writingPrompt: z.string(),
});

export type MockExam = z.infer<typeof MockExamSchema>;

// ──────────────────────────────────────────────────────────
// MOCK EXAM ATTEMPT (stored locally)
// ──────────────────────────────────────────────────────────
export interface MockExamScores {
  reading: { correct: number; total: number };
  qcm: { correct: number; total: number };
  writing: number | null; // 0-25, null if not graded
  overall: number; // 0-100 percentage
}

export type MockExamStatus = "active" | "completed" | "expired";

export interface MockExamAttempt {
  id: string;
  examId?: string; // identifier of the underlying pre-generated exam (e.g. "exam-03")
  exam: MockExam;
  status: MockExamStatus;
  startedAt: number; // epoch ms
  completedAt?: number;
  durationMinutes: number;
  // user inputs
  readingAnswers: Record<number, number>;
  qcmAnswers: Record<number, number>;
  writingText: string;
  // results (set on completion)
  scores?: MockExamScores;
  writingFeedback?: string; // HTML
}

export const MOCK_EXAM_DEFAULT_DURATION_MIN = 60;
